{"function": "() => {
    try {
        const scene = window.cc?.director?.getScene();
        if (!scene) return { error: 'No scene found', cc: !!window.cc };

        function dumpNode(node, depth = 0) {
            const indent = '  '.repeat(depth);
            const comps = node._components ? node._components.map(c => c.constructor?.name || c.__type__).join(',') : '';
            const info = `${indent}[${node.active ? 'ON' : 'OFF'}] "${node.name}" layer=${node.layer} comps=[${comps}]`;
            const children = (node._children || []).map(c => dumpNode(c, depth + 1));
            return [info, ...children].join('\n');
        }

        return { tree: dumpNode(scene) };
    } catch(e) {
        return { error: e.message, stack: e.stack };
    }
}"}

