{"function": "() => {
    function findComp(node, name) {
        const c = node._components?.find(c => c.constructor?.name === name);
        if (c) return c;
        for (const child of (node._children || [])) {
            const f = findComp(child, name);
            if (f) return f;
        }
        return null;
    }
    const scene = window.cc?.director?.getScene();
    const gm = findComp(scene, 'GameMain');
    const br = gm?._blockRenderer;

    // Render each sprite frame to a small canvas and measure opaque pixel area
    function measureOpaqueArea(spriteFrame) {
        const tex = spriteFrame?.texture;
        if (!tex || !tex._image) return 'no texture image';
        const img = tex._image._nativeData || tex._image._data || tex._image;
        if (!img || !(img instanceof HTMLImageElement || img instanceof HTMLCanvasElement)) {
            return 'no HTML image';
        }

        const canvas = document.createElement('canvas');
        canvas.width = 32; canvas.height = 32;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, 32, 32);
        const data = ctx.getImageData(0, 0, 32, 32).data;
        let opaquePixels = 0;
        for (let i = 3; i < data.length; i += 4) {
            if (data[i] > 128) opaquePixels++;
        }
        return { opaquePixels, pct: Math.round(opaquePixels * 100 / 1024) };
    }

    const results = {};
    const typeNames = ['I','O','T','S','Z','J','L'];
    for (let t = 0; t < 7; t++) {
        results[typeNames[t]] = measureOpaqueArea(br?._spriteFrames?.[t]);
    }
    return results;
}"}

