            const gx = x0 + px;
            const gy = y0 + py;

            // Dark border
            if (px < BORDER || px >= SIZE - BORDER || py < BORDER || py >= SIZE - BORDER) {
                set(gx, gy, rB, gB, bB);
            }
            // Bright bevel (top-left)
            else if (px < BORDER + BEVEL || py < BORDER + BEVEL) {
