const zlib = require('zlib');
// Read the I-piece (Cyan) from the generated file
const src = require('fs').readFileSync('assets/scripts/BlockTextures.ts', 'utf8');
const match = src.match(/static readonly I = '([^']+)'/);
const buf = Buffer.from(match[1], 'base64');

// Find and decompress IDAT
let pos = 8; // skip signature
while (pos < buf.length) {
    const len = buf.readUInt32BE(pos);
    const type = buf.slice(pos+4, pos+8).toString('ascii');
    if (type === 'IDAT') {
        const compressed = buf.slice(pos+8, pos+8+len);
        const raw = zlib.inflateSync(compressed);
        // Each row: 1 filter byte + 32*4 RGBA bytes
        // Check pixel at center (16,16)
        const y = 16, x = 16;
        const rowLen = 1 + 32*4;
        const i = y * rowLen + 1 + x*4;
        console.log('Center pixel RGBA:', raw[i], raw[i+1], raw[i+2], raw[i+3]);
        // Check pixel at border (0,0)
        const j = 0 * rowLen + 1 + 0*4;
        console.log('Border pixel RGBA:', raw[j], raw[j+1], raw[j+2], raw[j+3]);
        // Check pixel at highlight (3,3)
        const k = 3 * rowLen + 1 + 3*4;
        console.log('Highlight pixel RGBA:', raw[k], raw[k+1], raw[k+2], raw[k+3]);
        break;
    }
    pos += 4 + 4 + len + 4;
}
"
